B.push(
{id:"M5-01",m:5,q:"¿Cuál es la función principal de un Agente de Negociación?",o:["Intermediar en la compra y venta de valores en mercados autorizados","Custodiar los valores y fondos de sus clientes","Calificar el riesgo de los valores negociables","Asesorar sobre estrategias de inversión global"],a:0,e:"Según la guía, el AN intermedia en la compra y venta de valores en mercados autorizados; no custodia fondos ni valores.",r:"M5 · P1"},
{id:"M5-115",m:5,q:"¿Qué agente se encarga de la compensación y liquidación de operaciones?",o:["La cámara compensadora","El Agente de Negociación","El agente de custodia","El Agente Productor"],a:0,e:"Según la guía, la compensación y liquidación de las operaciones está a cargo de la cámara compensadora, que además garantiza esa liquidación.",r:"M5 · P2"},
{id:"M5-61",m:5,q:"¿Cuál es la responsabilidad clave de un agente de custodia?",o:["Calificar el riesgo de los valores que custodia","Administrar cuentas comitentes y custodiar valores","Fijar el precio de referencia de los valores","Autorizar la oferta pública de las emisiones"],a:1,e:"El agente de custodia lleva las cuentas comitentes y guarda los valores; no califica, no fija precios ni autoriza ofertas.",r:"M5 · P3"},
{id:"M5-62",m:5,q:"¿Qué agente asesora sobre estrategias de inversión global?",o:["El Agente de Negociación","El Agente Productor","El Agente de Calificación de Riesgo","El Agente Asesor Global de Inversión"],a:3,e:"Lo dice el nombre: el AAGI es el que asesora sobre inversiones y estrategias globales.",r:"M5 · P4"},
{id:"M5-63",m:5,q:"¿Cuál es una limitación de los Agentes de Negociación?",o:["No pueden asesorar sobre inversiones sin registro en la CNV","No pueden ingresar órdenes de clientes en mercados autorizados","No pueden operar por cartera propia","No pueden actuar nunca como hacedores de mercado"],a:0,e:"El asesoramiento requiere estar registrado en la CNV. El AN sí intermedia y, con convenio vigente con un ALyC Integral, puede ser hacedor de mercado.",r:"M5 · P5"},
{id:"M5-64",m:5,q:"¿Qué norma regula la inscripción de agentes en Argentina?",o:["La Ley 17.811","La Ley 26.831","La Ley 19.550","La Ley 24.083"],a:1,e:"La Ley 26.831 de Mercado de Capitales es la que regula la inscripción de los agentes ante la CNV.",r:"M5 · P6"},
{id:"M5-44",m:5,q:"¿Cuál es una característica de las acciones ordinarias?",o:["Otorgan preferencia en el cobro de dividendos, sin derecho a voto","Otorgan un interés fijo y el reembolso del capital al vencimiento","Otorgan derecho a voto y participación en utilidades","Otorgan voto múltiple y prioridad en la liquidación de la sociedad"],a:2,e:"Según la guía, la acción ordinaria da derecho a voto y a participar en las utilidades; un interés fijo con reembolso del capital es propio de un instrumento de deuda.",r:"M5 · P7"},
{id:"M5-116",m:5,q:"¿Qué define la política de dividendos?",o:["El directorio de la sociedad","La Comisión Nacional de Valores","La comisión fiscalizadora","La asamblea de accionistas"],a:3,e:"Según la guía, la política de dividendos la define la asamblea de accionistas, no el directorio ni la CNV.",r:"M5 · P8"},
{id:"M5-65",m:5,q:"¿Qué son las obligaciones negociables?",o:["Instrumentos de deuda emitidos por sociedades","Instrumentos de capital que otorgan derecho a voto","Cuotapartes de un fondo común de inversión","Contratos derivados sobre tasas de interés"],a:0,e:"La ON es deuda: la sociedad se financia y el inversor pasa a ser acreedor, no socio.",r:"M5 · P9"},
{id:"M5-66",m:5,q:"¿Qué operación corresponde al mercado primario?",o:["La reventa de valores entre inversores","La caución de valores en garantía","La negociación de contratos de futuros","La emisión inicial de valores por el emisor"],a:3,e:"En el primario el emisor coloca los valores por primera vez; la reventa entre inversores es mercado secundario.",r:"M5 · P10"},
{id:"M5-117",m:5,q:"¿Qué principio rige la prioridad en la negociación?",o:["Volumen-tiempo","Precio-cantidad","Precio-tiempo","Orden de llegada del cliente al agente"],a:2,e:"La guía lo resume en precio-tiempo: primero el mejor precio y, a igual precio, la orden más antigua.",r:"M5 · P11"},
{id:"M5-67",m:5,q:"¿Qué norma regula las plataformas de financiamiento colectivo?",o:["La Ley 25.246","La Ley 27.440","La Ley 24.083","La Ley 24.441"],a:1,e:"La Ley 27.440 de Financiamiento Productivo es la que regula las Plataformas de Financiamiento Colectivo.",r:"M5 · P12"},
{id:"M5-68",m:5,q:"¿Qué es un contrato de futuros?",o:["Un derecho, sin obligación, a comprar un activo a un precio fijado","Un intercambio de flujos a tasa fija por flujos a tasa variable","Un acuerdo para comprar o vender un activo en fecha futura a precio pactado","Un préstamo de dinero garantizado con valores negociables"],a:2,e:"El futuro obliga a las dos partes a una compraventa a fecha y precio pactados; el derecho sin obligación es la opción.",r:"M5 · P13"},
{id:"M5-69",m:5,q:"¿Qué representa la prima en una opción?",o:["La garantía que el comprador integra en la cámara","El costo que paga el comprador por el derecho","El precio de ejercicio del activo subyacente","La diferencia entre el precio del subyacente y el de ejercicio"],a:1,e:"La prima es el precio del derecho que adquiere el comprador. La diferencia entre subyacente y ejercicio es el valor intrínseco.",r:"M5 · P14"},
{id:"M5-54",m:5,q:"¿Cuál es el objetivo de un swap de tasa de interés?",o:["Intercambiar flujos a tasa fija por tasa variable","Comprar un activo a futuro a precio pactado","Obtener el derecho a vender un activo","Garantizar la liquidación de una operación"],a:0,e:"El swap de tasa intercambia flujos: los de una tasa fija contra los de una tasa variable.",r:"M5 · P15"},
{id:"M5-70",m:5,q:"¿Qué estrategia utiliza simultáneamente opciones call y put?",o:["El lanzamiento cubierto","La put protectora","El spread","La cobertura con futuros"],a:2,e:"Según la guía, el spread combina calls y puts. El lanzamiento cubierto y la put protectora usan un solo tipo de opción junto con el subyacente.",r:"M5 · P16"},
{id:"M5-118",m:5,q:"¿Cuál es el principal riesgo en derivados?",o:["Riesgo operativo","Riesgo de tipo de cambio","Riesgo de base","Riesgo de tasa de interés"],a:2,e:"La guía señala al riesgo de base como el principal riesgo en derivados: la diferencia que puede abrirse entre el precio del contrato y el del activo de contado.",r:"M5 · P17"},
{id:"M5-71",m:5,q:"¿Qué norma regula la operatoria de derivados en Argentina?",o:["La Ley 20.643","La Ley 24.441","La Ley 25.246","La Ley 26.831"],a:3,e:"La operatoria de derivados cae bajo la Ley 26.831 de Mercado de Capitales.",r:"M5 · P18"},
{id:"M5-09",m:5,q:"¿Qué función cumple la cámara compensadora?",o:["Autorizar la oferta pública de los valores","Llevar el registro de accionistas de las emisoras","Garantizar la liquidación de operaciones","Calificar el riesgo de las operaciones garantizadas"],a:2,e:"Según la guía, la cámara compensadora garantiza la liquidación de las operaciones; la oferta pública la autoriza la CNV.",r:"M5 · P19"},
{id:"M5-72",m:5,q:"¿Qué mecanismo asegura el cumplimiento de contratos en mercados de futuros?",o:["Las garantías","La prioridad precio-tiempo","El registro electrónico de órdenes","La calificación de riesgo de los agentes"],a:0,e:"Las garantías (márgenes) respaldan el cumplimiento de lo pactado en los contratos de futuros.",r:"M5 · P20"},
{id:"M5-12",m:5,q:"¿Qué significa “prioridad precio-tiempo”?",o:["Se ejecuta primero la orden de mayor volumen","Se ejecuta primero la orden del cliente sobre la del agente","Se ejecuta primero la orden con mejor precio y luego por antigüedad","Se ejecutan las órdenes en forma proporcional"],a:2,e:"Primero el mejor precio; a igualdad de precio, la antigüedad de la orden.",r:"M5 · P21"},
{id:"M5-73",m:5,q:"¿Qué operación se considera garantizada?",o:["Las operaciones con derivados en mercados autorizados","Las operaciones bilaterales concertadas fuera de mercado","Las compraventas directas entre particulares","Las colocaciones primarias por formación de libro"],a:0,e:"Los derivados negociados en mercados autorizados cuentan con la garantía del mercado o de la cámara.",r:"M5 · P22"},
{id:"M5-74",m:5,q:"¿Qué riesgo cubren las garantías en mercados de futuros?",o:["El riesgo de incumplimiento","El riesgo de tasa de interés","El riesgo de volatilidad del subyacente","El riesgo de liquidez del contrato"],a:0,e:"Las garantías cubren la posibilidad de que una de las partes no cumpla con su obligación.",r:"M5 · P23"},
{id:"M5-75",m:5,q:"¿Qué norma regula los mecanismos de liquidación y compensación?",o:["Normas CNV, Título II","Normas CNV, Título XI","Normas CNV, Título XVIII","Normas CNV, Título VI"],a:3,e:"La guía ubica la liquidación y compensación en el Título VI de las Normas CNV.",r:"M5 · P24"},
{id:"M5-119",m:5,q:"¿Qué ley regula el mercado de capitales en Argentina?",o:["La Ley 17.811","La Ley 26.831","La Ley 19.550","La Ley 24.083"],a:1,e:"La Ley 26.831 es la Ley de Mercado de Capitales: la que hoy regula el mercado de capitales en Argentina.",r:"M5 · P25"},
{id:"M5-120",m:5,q:"¿Qué ley introdujo las plataformas de financiamiento colectivo?",o:["La Ley 26.831","La Ley 27.739","La Ley 24.441","La Ley 27.440"],a:3,e:"La Ley 27.440 de Financiamiento Productivo es la que incorporó las Plataformas de Financiamiento Colectivo.",r:"M5 · P26"},
{id:"M5-121",m:5,q:"¿Qué norma establece la obligación de inscripción de agentes?",o:["La Ley 19.550","La Ley 26.831","La Ley 21.526","La Ley 24.083"],a:1,e:"La obligación de inscribirse como agente ante la CNV la establece la Ley 26.831 de Mercado de Capitales.",r:"M5 · P27"},
{id:"M5-76",m:5,q:"¿Qué artículo de la Ley 26.831 regula la función de la Comisión Nacional de Valores?",o:["Art. 2","Art. 1","Art. 47","Art. 132"],a:0,e:"Según la guía, es el art. 2 de la Ley 26.831.",r:"M5 · P28"},
{id:"M5-77",m:5,q:"¿Qué norma regula las operaciones garantizadas?",o:["Normas CNV, Título III","Normas CNV, Título XIV","Normas CNV, Título X","Normas CNV, Título XVI"],a:1,e:"La guía remite al Título XIV de las Normas CNV para las operaciones garantizadas.",r:"M5 · P29"},
{id:"M5-122",m:5,q:"¿Qué ley regula las obligaciones negociables?",o:["La Ley 23.576","La Ley 24.083","La Ley 19.550","La Ley 24.441"],a:0,e:"Según la guía, las obligaciones negociables se rigen por la Ley 23.576.",r:"M5 · P30"},
{id:"M5-11",m:5,q:"Las operaciones con valores negociables deben ser realizadas, como regla general, en:",o:["Segmentos de negociación bilateral, entre Agentes por cartera propia o con inversores calificados","Operaciones concertadas fuera de mercado entre Agentes, informadas luego al Mercado","Subastas organizadas por el emisor con la garantía de un banco colocador","Segmentos de negociación por interferencia de ofertas con prioridad precio tiempo y garantía de los Mercados o Cámaras Compensadoras"],a:3,e:"La regla es el segmento de interferencia de ofertas con prioridad precio-tiempo y garantía del Mercado o Cámara; el bilateral es la excepción.",r:"M5 · P31"},
{id:"M5-27",m:5,q:"Los Agentes habilitados a actuar como Hacedores de Mercado pueden hacerlo en el:",o:["Segmento de negociación bilateral exclusivamente","Mercado primario únicamente, durante la colocación","Segmento de negociación de PyMEs exclusivamente","Segmento de negociación con prioridad precio tiempo y concurrencia de ofertas"],a:3,e:"El hacedor de mercado provee liquidez en el segmento de concurrencia de ofertas con prioridad precio-tiempo.",r:"M5 · P32"},
{id:"M5-14",m:5,q:"¿Qué órdenes deben registrarse en el sistema electrónico de registro de órdenes, para realizar operaciones?",o:["Sólo las de clientes minoristas a ejecutarse en segmentos de concurrencia de ofertas, quedando excluidas las de cartera propia","Las correspondientes a clientes y a la cartera propia del Agente a ejecutarse en segmentos de concurrencia de ofertas con prioridad precio tiempo y aquellas a ejecutarse en segmentos de negociación bilateral","Sólo las órdenes que superen el monto mínimo que fije el Mercado","Sólo las órdenes efectivamente ejecutadas, una vez concertadas en el Mercado"],a:1,e:"Se registran las de clientes y las de cartera propia, tanto en los segmentos de concurrencia de ofertas como en los bilaterales.",r:"M5 · P33"},
{id:"M5-15",m:5,q:"Son operaciones de cartera propia, las realizadas por:",o:["Los clientes institucionales y los inversores calificados que operan a través del Agente","Los agentes productores vinculados, por las órdenes que acercan de sus clientes","Los fondos comunes de inversión administrados por sociedades gerentes vinculadas al Agente","Los miembros de los órganos de administración y fiscalización, síndicos, consejeros de vigilancia, gerentes, socios, accionistas, empleados, administradores, apoderados y representantes de ese Agente"],a:3,e:"La definición es amplia: alcanza a todo el entorno del agente (órganos, socios, empleados, apoderados), no sólo a la sociedad.",r:"M5 · P34"},
{id:"M5-13",m:5,q:"En los segmentos para la negociación bilateral, la misma se lleva a cabo:",o:["Entre cualquier par de inversores minoristas","Sólo entre el emisor y los colocadores","Sólo entre Agentes, por cuenta de sus clientes minoristas","Entre Agentes de su cartera propia y/o entre Agentes e inversores/clientes calificados"],a:3,e:"El segmento bilateral está reservado a la cartera propia de los agentes y a los inversores calificados.",r:"M5 · P35"},
{id:"M5-10",m:5,q:"El fondo de garantía obligatorio, dispuesto en la Ley de Mercado de Capitales para los Mercados/Cámaras Compensadoras, cubre los compromisos:",o:["De los clientes frente a sus agentes","De las emisoras frente a los tenedores de sus valores","De los agentes frente a la CNV","No cumplidos entre Agentes, originados en operaciones con garantía de liquidación del Mercado/CC"],a:3,e:"Cubre los incumplimientos entre agentes en operaciones con garantía de liquidación del Mercado o la Cámara, no los de clientes ni emisoras.",r:"M5 · P36"},
{id:"M5-78",m:5,q:"Los fondos líquidos pertenecientes a un cliente que opera mediante instrucciones específicas a su Agente, deben:",o:["Invertirse automáticamente en un FCI de mercado de dinero","Transferirse a una cuenta del mercado hasta su uso","Ser tratados conforme lo convenido expresamente con el cliente","Devolverse al cliente al cierre de cada jornada"],a:2,e:"Si el cliente opera por instrucción específica, el destino de sus fondos líquidos es el que pactó expresamente con el agente.",r:"M5 · P37"},
{id:"M5-16",m:5,q:"Se entiende que existe una “instrucción específica” para una operación cuando:",o:["El cliente firma el convenio de apertura de cuenta con el Agente","El cliente autoriza al Agente a operar discrecionalmente dentro de su perfil de riesgo","Por cada operación se indiquen al menos la especie/instrumento que se quiere operar, cantidad, precio o rango de precio y/o tasa de rendimiento","La orden se cursa por escrito y queda registrada en el sistema del Agente"],a:2,e:"Especie + cantidad + precio/rango o tasa, operación por operación.",r:"M5 · P38"},
{id:"M5-03",m:5,q:"Identifique las limitaciones o prohibiciones de la actuación de los Agentes Productores:",o:["Realizar actividades de difusión del mercado de capitales","Vincularse con un Agente Asesor Global de Inversión","Custodiar Fondos y/o Valores Negociables de clientes o en nombre de clientes","Contactar a potenciales clientes minoristas"],a:2,e:"El AP difunde y acerca clientes, pero nunca toca fondos ni valores. Puede estar vinculado a un AAGI.",r:"M5 · P39"},
{id:"M5-79",m:5,q:"En las operaciones de venta con liquidación en contado normal, en forma previa a dar curso a las órdenes de los clientes, los Agentes podrán:",o:["Solicitar autorización previa al mercado en el que se ejecutará la venta","Exigir al cliente una garantía en efectivo por el total de la venta","Registrar la orden ante la CNV y esperar su conformidad","Constatar la disponibilidad/titularidad de los valores negociables en la cuenta comitente del cliente (o el esquema de préstamo/habilitación que corresponda)"],a:3,e:"Antes de vender, el agente puede verificar que el cliente tenga los valores en su cuenta o el préstamo que habilite la venta.",r:"M5 · P40"},
{id:"M5-17",m:5,q:"Una venta en corto es una operación de:",o:["Venta de valores propios con liquidación en contado normal","Venta de contratos de futuro sin integrar márgenes de garantía","Venta a plazo firme con cancelación anticipada pactada","Venta de valores negociables obtenidos a través de préstamos de valores negociables concertados en la misma jornada de negociación"],a:3,e:"Se vende con valores tomados en préstamo en la misma rueda.",r:"M5 · P41"},
{id:"M5-18",m:5,q:"En las operaciones de préstamos de valores, los Agentes deben requerir:",o:["Sólo la conformidad escrita del cliente tomador, ya que el prestamista no asume riesgo","Conformidad escrita del cliente prestamista para su realización y autorización suscripta por el cliente tomador a favor de su Agente","Autorización previa de la CNV para cada operación de préstamo","Garantía de una entidad financiera a favor del cliente prestamista"],a:1,e:"Conformidad escrita de ambas puntas: la del prestamista para hacerla y la autorización del tomador a favor de su agente.",r:"M5 · P42"},
{id:"M5-21",m:5,q:"En la fecha de concertación de una operación de caución el tomador de fondos recibe:",o:["El valor de mercado íntegro de la garantía","El valor aforado más los intereses","El valor nominal de los títulos entregados","El valor aforado de la garantía menos los intereses"],a:3,e:"El tomador recibe el aforado menos los intereses; al vencimiento devuelve el aforado más intereses y gastos.",r:"M5 · P43"},
{id:"M5-80",m:5,q:"En la fecha de cancelación de una operación de caución el colocador de fondos cobra:",o:["El valor aforado de la garantía, sin intereses ni gastos","El valor de mercado de la garantía al vencimiento","El valor aforado de la garantía más los intereses neto de gastos","Los valores caucionados, al último precio de cierre"],a:2,e:"El colocador recupera lo prestado con sus intereses, y de ahí se descuentan los gastos.",r:"M5 · P44"},
{id:"M5-19",m:5,q:"El tomador de fondos:",o:["En la operación de pase pierde la propiedad de los valores objeto de la operación y en la operación de caución no","En ambas operaciones, pase y caución, conserva la propiedad de los valores","En ambas operaciones, pase y caución, pierde la propiedad de los valores","En la operación de caución pierde la propiedad de los valores y en la operación de pase no"],a:0,e:"El pase transfiere la propiedad; la caución deja los valores en garantía. Es la diferencia clásica entre ambas.",r:"M5 · P45"},
{id:"M5-51",m:5,q:"Los vendedores de Call están obligados a vender el activo subyacente si el comprador ejerce la opción. Esta afirmación es:",o:["Verdadera","Falsa: pueden desistir pagando la prima","Falsa","Verdadera únicamente en opciones europeas"],a:0,e:"El comprador tiene el derecho; el lanzador, la obligación. La prima es el precio de ese derecho.",r:"M5 · P46"},
{id:"M5-50",m:5,q:"Los contratos de futuros agrícolas son:",o:["Contratos estandarizados para recibir la entrega de una mercadería en un lugar y fecha específicos","Contratos a medida entre las partes, negociados fuera de mercado","Contratos que otorgan un derecho pero no una obligación de entrega","Contratos que se liquidan siempre por diferencias, sin entrega"],a:0,e:"El futuro es un contrato estandarizado, con entrega en lugar y fecha específicos; la opción es la que da derecho sin obligación.",r:"M5 · P47"},
{id:"M5-49",m:5,q:"Los márgenes de garantía en la negociación de futuros:",o:["Constituyen el precio del contrato","Son la prima que cobra el vendedor","Sirven como garantía de cumplimiento","Se integran sólo al vencimiento"],a:2,e:"Según la guía, los márgenes sirven como garantía de cumplimiento del contrato; no son su precio ni una prima.",r:"M5 · P48"},
{id:"M5-38",m:5,q:"Los Agentes, en la documentación de respaldo que extiendan a sus clientes por las operaciones realizadas (boletos), deben:",o:["Indicar sólo el precio neto de la operación","Detallar la cartera completa del cliente","Explicitar las comisiones y todo otro costo de intermediación","Informar el resultado impositivo de la operación"],a:2,e:"Transparencia de costos: comisiones y todo otro costo de intermediación explicitados en el boleto.",r:"M5 · P49"},
{id:"M5-58",m:5,q:"Según la Ley de Mercado de Capitales N° 26.831, la aplicación de sanciones a los Agentes le corresponde a:",o:["El mercado donde operan","La cámara compensadora","La UIF","La Comisión Nacional de Valores"],a:3,e:"Según la Ley 26.831, sancionar a los agentes le corresponde a la CNV, no a los mercados ni a las cámaras.",r:"M5 · P50"},
{id:"M5-30",m:5,q:"Requisito previo a la negociación de un Cheque de Pago Diferido:",o:["Su calificación por un Agente de Calificación de Riesgo","La conformidad previa del banco girado","Endoso con especificación de que el CPD será negociado en Mercados regulados por la CNV","El aval de una entidad financiera en todos los casos"],a:2,e:"Endoso con leyenda expresa de que se negociará en mercados regulados por la CNV.",r:"M5 · P51"},
{id:"M5-31",m:5,q:"La negociación de Cheques de Pago Diferido en el segmento directo:",o:["Solamente pueden negociarse instrumentos cuyo vencimiento se produzca a partir de los 30 días corridos desde la fecha de su libramiento","Solamente pueden negociarse instrumentos cuyo vencimiento se produzca a partir de los 10 días hábiles desde la fecha de la decisión de negociarlo","Solamente pueden negociarse instrumentos cuyo vencimiento se produzca a partir de los 20 días corridos desde la fecha de la decisión de descontarlo/negociarlo en el mercado de capitales","Solamente pueden negociarse instrumentos cuyo vencimiento no supere los 60 días corridos desde la fecha de su emisión"],a:2,e:"En el segmento directo el piso es de 20 días corridos, contados desde que se decide descontar o negociar el cheque.",r:"M5 · P52"},
{id:"M5-33",m:5,q:"Si una PyME decide negociar una Factura de Crédito Electrónica (FCE) en Mercados regulados por la CNV, deberá:",o:["Solicitar autorización de oferta pública","Obtener el aval de una SGR","Presentar estados contables auditados","Abrir cuenta apta para la negociación del instrumento y solicitar la acreditación del instrumento en la misma"],a:3,e:"Según la guía, la PyME necesita una cuenta apta para negociar la FCE y pedir que el instrumento se acredite en ella.",r:"M5 · P53"},
{id:"M5-35",m:5,q:"La negociación del instrumento pagaré requiere:",o:["Su aval por una entidad financiera","El cumplimiento de los montos y plazos mínimos que fija la CNV","Autorización de oferta pública","La intervención de un escribano"],a:1,e:"La CNV fija montos y plazos mínimos para negociar el pagaré.",r:"M5 · P54"},
{id:"M5-34",m:5,q:"Negociación de Factura de Crédito Electrónica en moneda extranjera:",o:["La gran empresa deberá cancelarla necesariamente en la moneda de origen","No está permitida la negociación de FCE en moneda extranjera","La moneda de cancelación la define el tenedor de la factura","La gran empresa deberá cancelar la deuda en pesos, conforme el reglamento del Agente de Registro y Pago de FCE"],a:3,e:"Según la guía, la gran empresa cancela en pesos, conforme el reglamento del Agente de Registro y Pago de FCE.",r:"M5 · P55"},
{id:"M5-83",m:5,q:"Cuando una PyME decide descontar una Factura de Crédito Electrónica en Mercados regulados por la CNV, la factura:",o:["Se cancela en la moneda que elija el tenedor","Debe ser cancelada conforme surja del reglamento del Agente de Registro y Pago o entidad que cumpla el rol de clearing","La cancela el mercado con su fondo de garantía","Se cancela según lo que acuerden libremente el agente y la PyME"],a:1,e:"La cancelación de la FCE negociada sigue el reglamento del Agente de Registro y Pago o del clearing.",r:"M5 · P56"},
{id:"M5-32",m:5,q:"En la negociación de Cheques de Pago Diferido, los Agentes deberán:",o:["Garantizar con fondos propios el pago del cheque al inversor ante defectos formales o falta de fondos del librador","Retener el 10% del monto negociado como garantía hasta la fecha de pago del cheque","Registrar cada cheque ante la CNV e informar al cliente sólo el resultado de la negociación","Notificar fehacientemente y bajo su responsabilidad a los clientes las modalidades de negociación de CPD, sus características distintivas y esquemas de garantías, y los eventuales riesgos ante el no pago del cheque y el procedimiento posterior aplicable"],a:3,e:"Deber de información reforzado: modalidades, garantías de cada una y qué pasa si el cheque no se paga por defectos formales o falta de fondos.",r:"M5 · P57"},
{id:"M5-36",m:5,q:"Para los clientes de los Agentes que estén autorizados a operar ADM (Acceso Directo al Mercado), la redistribución de la información de Mercado (Market Data) en tiempo real por parte de los Agentes:",o:["Corre por cuenta exclusiva del Agente, sin arancel","Está prohibida","Requiere autorización previa de la CNV","Está sujeta a los aranceles fijados por el Mercado en cuestión"],a:3,e:"La información de mercado en tiempo real que el agente redistribuye a sus clientes ADM tiene el arancel que fije el Mercado.",r:"M5 · P58"},
{id:"M5-37",m:5,q:"Respecto de los saldos de valores negociables, instrumentos o fondos en custodia en el Agente Depositario Central de Valores Negociables (ADCVN), ante la disconformidad del tenedor titular:",o:["Sólo puede reclamar ante su Agente","Podrá realizar el reclamo ante el ADCVN, su Agente y la CNV","Debe iniciar una acción judicial directa","Debe reclamar ante el mercado donde operó"],a:1,e:"Tres vías de reclamo: el ADCVN, su agente y la CNV.",r:"M5 · P59"},
{id:"M5-39",m:5,q:"Los Agentes pueden trasladar a sus clientes:",o:["Las multas que les aplique la CNV","Los costos de su sistema de prevención de lavado","Los costos del mantenimiento de cuenta/s derivados de los servicios que prestan como depositantes en el ADCVN","Las pérdidas por operaciones mal ejecutadas"],a:2,e:"Se pueden trasladar los costos de mantenimiento de cuentas por los servicios que prestan como depositantes en el depositario central.",r:"M5 · P60"},
{id:"M5-40",m:5,q:"La regulación de C.N.V. respecto de las Plataformas de Financiamiento Colectivo incluye:",o:["Sólo plataformas de préstamos entre particulares","Sólo plataformas de donaciones","Plataformas orientadas a financiación bajo el esquema de equity","Plataformas de intercambio de activos virtuales"],a:2,e:"Según la guía, la regulación de la CNV sobre PFC incluye las plataformas de financiación bajo el esquema de equity.",r:"M5 · P61"},
{id:"M5-84",m:5,q:"Respecto de los proyectos ofrecidos a través de las Plataformas de Financiamiento Colectivo (PFC):",o:["Deben ser PyMEs con Certificado MiPyME emitido por la CNV","Deben contar con calificación de riesgo previa","Deben tener autorización de oferta pública del BCRA","Deben revestir la calidad de Emprendimiento Argentino conforme la reglamentación del Ministerio de Economía"],a:3,e:"El requisito es ser Emprendimiento Argentino según la reglamentación del Ministerio de Economía.",r:"M5 · P62"},
{id:"M5-02",m:5,q:"Los Agentes de Negociación no pueden:",o:["Ingresar órdenes en los segmentos de concurrencia de ofertas","Efectuar custodia de valores negociables, fondos y ser depositantes en el Agente Depositario Central de Valores Negociables","Actuar como hacedores de mercado con convenio vigente con un ALyC Integral","Recibir órdenes de clientes por los medios convenidos"],a:1,e:"La custodia de valores y fondos no es del AN: no puede custodiarlos ni ser depositante en el ADCVN.",r:"M5 · P63"},
{id:"M5-85",m:5,q:"Los Agentes Asesores Globales de Inversión pueden:",o:["Custodiar fondos y valores de sus clientes","Ofrecer públicamente valores sin autorización de oferta pública en Argentina","Realizar operaciones por medio de intermediarios locales y del exterior","Ser clientes del AN con quien celebraron convenio"],a:2,e:"El AAGI opera a través de intermediarios locales y del exterior. Ofrecer valores sin OP local y ser cliente del AN con el que tiene convenio le están prohibidos.",r:"M5 · P64"},
{id:"M5-123",m:5,q:"Los Agentes de Calificación de Riesgo pueden:",o:["Realizar actividades afines, si realizan el trámite de autorización previa ante la CNV","Realizar cualquier actividad comercial, sin necesidad de autorización de la CNV","Emitir recomendaciones de compra o venta de los instrumentos que califican","Custodiar los valores negociables que califican"],a:0,e:"Según la guía, los ACR pueden hacer actividades afines siempre que tramiten antes la autorización ante la CNV.",r:"M5 · P65"},
{id:"M5-08",m:5,q:"Los Agentes de Calificación de Riesgo:",o:["Pueden calificar valores negociables con oferta pública y privada","Sólo pueden calificar valores con oferta pública","Sólo pueden calificar valores con oferta privada","Deben abstenerse de calificar fideicomisos financieros"],a:0,e:"Según la guía, pueden calificar valores negociables tanto con oferta pública como con oferta privada.",r:"M5 · P66"},
{id:"M5-86",m:5,q:"Los Agentes Productores pueden:",o:["Custodiar valores negociables de sus clientes","Realizar actividades de difusión del Mercado de Capitales vinculados a un Agente Asesor Global de Inversión (AAGI)","Recibir fondos de clientes en nombre del agente","Liquidar las operaciones de sus clientes"],a:1,e:"El AP difunde y acerca clientes, y puede hacerlo vinculado a un AAGI; nunca toca fondos ni valores.",r:"M5 · P67"},
{id:"M5-87",m:5,q:"Normas de conducta que debe cumplir un Agente Productor (AP):",o:["Garantizar al inversor un rendimiento mínimo","Administrar en forma discrecional la cartera del inversor","Brindar información adecuada en lenguaje apropiado, que le permita al inversor conocer los riesgos que asume en la o las inversiones","Recomendar los productos que le generen mayor comisión"],a:2,e:"El deber central es informar con claridad para que el inversor entienda los riesgos de su inversión.",r:"M5 · P68"},
{id:"M5-05",m:5,q:"Un Agente ALyC que posee la autorización del comitente para cumplir con la función de administración discrecional de cartera:",o:["Debe pedir instrucción específica para cada operación","No puede operar derivados en ningún caso","Debe informar cada orden a la CNV","Puede invertir los saldos en beneficio del cliente"],a:3,e:"La administración discrecional habilita a invertir los saldos en beneficio del cliente.",r:"M5 · P69"},
{id:"M5-06",m:5,q:"El ALyC tiene facultades para:",o:["Garantizar rendimientos mínimos a sus clientes","Ofrecer adelantos transitorios, con fondos propios por eventos que generen descalce o demoras transitorias","Emitir valores negociables por cuenta propia","Actuar como fiduciario financiero sin registro"],a:1,e:"Adelantos transitorios con fondos propios ante descalces o demoras, sí. Garantizar resultados, nunca.",r:"M5 · P70"},
{id:"M5-60",m:5,q:"El cheque de pago diferido goza de oferta pública en los términos de la Ley de Mercado de Capitales N° 26.831 y podrá ser negociado en Mercados bajo competencia de esta Comisión. Esta afirmación es:",o:["Falsa: requiere autorización expresa para cada emisión","Verdadera","Falsa","Verdadera sólo en el segmento avalado"],a:1,e:"Verdadera: el CPD tiene oferta pública por la propia Ley 26.831 y se negocia en mercados bajo competencia de la CNV.",r:"M5 · P71"},
{id:"M5-124",m:5,q:"La colocación primaria de valores negociables podrá efectuarse por los mecanismos de:",o:["Formación de libro o subasta o licitación pública","Negociación bilateral entre el emisor y cada inversor calificado","Interferencia de ofertas con prioridad precio-tiempo en el segmento garantizado","Adjudicación directa por parte de la CNV"],a:0,e:"Según la guía, la colocación primaria se hace por formación de libro o por subasta o licitación pública.",r:"M5 · P72"},
{id:"M5-88",m:5,q:"Se considera rotación excesiva de cartera a aquella actividad realizada por el AAGI que responde a la recepción de órdenes impartidas por el cliente, cuando las mismas superan el perfil de riesgo definido por el Agente para su cliente. Esta afirmación es:",o:["Falsa","Verdadera","Verdadera sólo para clientes minoristas","Verdadera sólo si el cliente no firmó el convenio"],a:0,e:"Falsa según la guía: la actividad descripta responde a órdenes impartidas por el propio cliente, y así planteada no configura rotación excesiva.",r:"M5 · P73"},
{id:"M5-59",m:5,q:"Para recibir órdenes e instrucciones de clientes, los Agentes pueden:",o:["Utilizar cualquier medio, sin necesidad de acuerdo previo","Utilizar los medios o modalidades de contacto convenidos con cada cliente en el Convenio de Apertura de Cuenta","Recibirlas únicamente por escrito y con firma certificada","Recibirlas sólo mediante grabación telefónica"],a:1,e:"Los medios habilitados son los pactados con cada cliente en el convenio de apertura de cuenta.",r:"M5 · P74"},
{id:"M5-04",m:5,q:"El Agente Asesor Global de Inversión NO puede:",o:["Ofrecer públicamente valores negociables que no cuenten con autorización de oferta pública en la República Argentina, ni ser cliente del AN con quien celebre convenio","Realizar operaciones por medio de intermediarios locales y del exterior","Asesorar sobre carteras de inversión","Vincularse con agentes productores"],a:0,e:"Sí puede operar por intermediarios locales y del exterior; lo prohibido es ofrecer VN sin OP local y ser cliente del AN con el que tiene convenio.",r:"M5 · P75"},
{id:"M5-57",m:5,q:"La competencia disciplinaria, a la cual quedan sometidos los Agentes registrados y con matrícula CNV, no es exclusiva de esta última. Esta afirmación es:",o:["Verdadera","Falsa","Verdadera sólo respecto de los ALyC","Verdadera: también la ejercen los Mercados"],a:1,e:"Falsa: la competencia disciplinaria sobre los agentes es exclusiva de la CNV; lo que comparten los Mercados y Cámaras es la supervisión y el control.",r:"M5 · P76"},
{id:"M5-89",m:5,q:"Las actividades de supervisión, fiscalización y control, sobre los Agentes registrados en la CNV y con membresía en Mercados, no resultan competencia exclusiva de la CNV. Esta afirmación es:",o:["Falsa","Verdadera","Falsa: sólo la CNV puede controlarlos","Verdadera sólo respecto de los Agentes Productores"],a:1,e:"Verdadera: los mercados y cámaras también supervisan a sus miembros. Lo exclusivo de la CNV es la potestad disciplinaria.",r:"M5 · P77"},
{id:"M5-90",m:5,q:"Los Mercados y las Cámaras Compensadoras deben denunciar toda falta en que incurrieren sus Agentes miembros, que resulten de las auditorías y controles de supervisión, fiscalización y control practicados por ellos. Esta afirmación es:",o:["Falsa: sólo deben sancionarla ellos mismos","Verdadera","Falsa","Verdadera sólo si la falta es grave"],a:1,e:"Verdadera: como la sanción es de la CNV, lo que detectan mercados y cámaras en sus controles debe ser denunciado.",r:"M5 · P78"},
{id:"M5-26",m:5,q:"Las operaciones a plazo firme pueden ser realizadas:",o:["Sobre cualquier valor negociable o instrumento negociado en el mercado, incluidos cheques de pago diferido y pagarés","Únicamente sobre valores negociables de renta fija y variable, excluidos cheques de pago diferido, letras de cambio, pagarés, certificados de depósito, warrants y certificados de depósito a plazo fijo","Únicamente sobre títulos públicos nacionales, excluidas las acciones y las obligaciones negociables","Únicamente sobre acciones y cheques de pago diferido, excluidos los valores de renta fija"],a:1,e:"Renta fija y variable, con exclusión expresa de CPD, letras, pagarés, certificados de depósito, warrants y plazos fijos.",r:"M5 · P79"},
{id:"M5-125",m:5,q:"Las operaciones de pase pueden ser realizadas:",o:["Únicamente sobre títulos públicos y letras del Tesoro, excluidas las acciones y los cheques de pago diferido","Sobre cualquier instrumento negociado en el mercado, incluidos pagarés, warrants y certificados de depósito a plazo fijo","Únicamente sobre acciones con oferta pública, excluidos todos los valores de renta fija","Únicamente sobre valores negociables de renta fija y variable, excluidos cheques de pago diferido, letras de cambio, pagarés, certificados de depósito, warrants y certificados de depósito a plazo fijo"],a:3,e:"Igual que el plazo firme: renta fija y variable, sin CPD, letras de cambio, pagarés, certificados de depósito, warrants ni plazos fijos.",r:"M5 · P80"},
{id:"M5-126",m:5,q:"En las operaciones de pase, el comprador a plazo firme:",o:["No puede cancelar anticipadamente la compra antes del vencimiento pactado","Puede cancelar anticipadamente abonando el importe pactado más una penalidad","Puede cancelar anticipadamente sólo con la conformidad del vendedor","Puede cancelar anticipadamente tal compra abonando el mismo importe que correspondería pagar en la fecha del vencimiento pactado"],a:3,e:"Según la guía, el comprador a plazo firme puede cancelar antes, pagando el mismo importe que le tocaría pagar al vencimiento.",r:"M5 · P81"},
{id:"M5-20",m:5,q:"Las acreencias devengadas durante la vigencia de una operación:",o:["De caución corresponden al tomador de fondos, de pase corresponden al colocador","Corresponden siempre al colocador de fondos","Corresponden siempre al tomador de fondos","De caución corresponden al colocador de fondos, de pase corresponden al tomador"],a:0,e:"Coherente con la propiedad: en la caución los valores siguen siendo del tomador, en el pase pasan al colocador.",r:"M5 · P82"},
{id:"M5-25",m:5,q:"En las operaciones de caución, el tomador de fondos:",o:["No puede cancelar anticipadamente la operación antes del vencimiento pactado","Puede cancelar anticipadamente pagando sólo los intereses devengados hasta ese día","Puede cancelar anticipadamente la operación abonando el mismo importe que correspondería pagar en la fecha del vencimiento pactado","Puede cancelar anticipadamente sólo con autorización previa del Mercado"],a:2,e:"La cancelación anticipada es posible pagando lo mismo que se pagaría al vencimiento.",r:"M5 · P83"},
{id:"M5-24",m:5,q:"En la fecha de concertación de una operación de caución la especie entregada en garantía se valoriza considerando:",o:["El precio de contado inmediato del momento de la caución","El precio promedio ponderado de la rueda","El valor nominal de la especie","El último precio de cierre de la especie para liquidar en contado normal"],a:3,e:"Último cierre de contado normal, no el precio del momento ni el de contado inmediato.",r:"M5 · P84"},
{id:"M5-81",m:5,q:"En la fecha de concertación de una operación de caución el colocador entrega:",o:["El valor aforado de la garantía menos los intereses","El valor aforado de la garantía más los intereses","El valor de mercado íntegro de la garantía","El valor nominal de la especie caucionada"],a:0,e:"Es la otra cara de lo que recibe el tomador: aforado menos intereses.",r:"M5 · P85"},
{id:"M5-82",m:5,q:"En la fecha de vencimiento de una operación de caución el tomador devuelve:",o:["El valor aforado de la garantía más los intereses y gastos","Sólo los intereses y los gastos","El valor de mercado de la garantía","Los valores caucionados al último precio de cierre"],a:0,e:"Al vencimiento el tomador cancela la deuda con sus intereses y los gastos, y recupera los valores dados en garantía.",r:"M5 · P86"},
{id:"M5-07",m:5,q:"El ALyC sólo puede realizar como actividades complementarias aquellas sujetas al control de la CNV y quedan exceptuados de dicha limitación los Bancos y Entidades Financieras autorizadas a funcionar en los términos de la Ley N° 21.526. Esta afirmación es:",o:["Falsa: puede realizar cualquier actividad comercial","Verdadera","Falsa: los bancos también están alcanzados por la limitación","Verdadera sólo para los ALyC Propios"],a:1,e:"Verdadera. Las entidades financieras de la Ley 21.526 quedan exceptuadas de esa limitación.",r:"M5 · P87"},
{id:"M5-91",m:5,q:"Los Mercados y las Cámaras Compensadoras desempeñarán el rol y funciones de contraparte central (CCP), cuando no garanticen el cumplimiento de las operaciones autorizadas por la CNV. Esta afirmación es:",o:["Falsa","Verdadera","Verdadera sólo en el segmento bilateral","Verdadera sólo para derivados"],a:0,e:"Falsa: actúan como contraparte central justamente cuando garantizan el cumplimiento de las operaciones.",r:"M5 · P88"},
{id:"M5-29",m:5,q:"Los ALyC Integrales, los ALyC Propios, los ALyC Agro y los AN (con convenio vigente con el respectivo ALyC Integral) son las únicas subcategorías y categoría de Agentes autorizados y registrados por la CNV que pueden revestir la calidad de Hacedores de Mercado. Esta afirmación es:",o:["Verdadera","Falsa: cualquier agente registrado ante la CNV puede serlo","Falsa","Verdadera, aunque los AN no necesitan convenio con un ALyC Integral"],a:0,e:"Verdadera: es una lista cerrada, y los AN entran sólo con convenio vigente con el respectivo ALyC Integral.",r:"M5 · P89"},
{id:"M5-28",m:5,q:"La función del Hacedor de Mercado es la de proveer liquidez a las especies y/o instrumentos sobre los que opere en orden a la formación más eficiente del precio y a la consiguiente reducción de su volatilidad. Esta afirmación es:",o:["Verdadera","Falsa","Falsa: su función es garantizar el precio de la especie","Verdadera sólo en el segmento bilateral"],a:0,e:"Verdadera: el hacedor provee liquidez para que el precio se forme de manera más eficiente y baje su volatilidad.",r:"M5 · P90"},
{id:"M5-92",m:5,q:"El Hacedor de Mercado, para cumplir su función, debe formular ofertas de compra y de venta con un mínimo diferencial entre sus respectivos precios, según el instrumento o la especie y bajo las condiciones que el Mercado establezca. Esta afirmación es:",o:["Falsa","Verdadera","Falsa: sólo debe formular ofertas de compra","Falsa: el diferencial lo define libremente el hacedor"],a:1,e:"Verdadera: proveer liquidez implica estar de los dos lados, con un diferencial mínimo según las condiciones del Mercado.",r:"M5 · P91"},
{id:"M5-93",m:5,q:"El Hacedor de Mercado actúa exclusivamente por cuenta de terceros. Esta afirmación es:",o:["Verdadera","Falsa","Verdadera sólo para los AN","Verdadera sólo durante el período de presencia"],a:1,e:"Falsa: no actúa exclusivamente por cuenta de terceros; provee liquidez operando también por cuenta propia.",r:"M5 · P92"},
{id:"M5-94",m:5,q:"Durante el período de presencia en la sesión de negociación, el Hacedor de Mercado no sólo podrá actuar en tal carácter con las especies y/o instrumentos para los que se encuentre habilitado por el respectivo Mercado. Esta afirmación es:",o:["Verdadera","Verdadera, con aviso previo al Mercado","Verdadera sólo para títulos públicos","Falsa"],a:3,e:"Falsa: sólo puede actuar como hacedor en las especies o instrumentos para los que el Mercado lo habilitó.",r:"M5 · P93"},
{id:"M5-95",m:5,q:"El Hacedor de Mercado, bajo su entera responsabilidad e independientemente que se encuentre habilitado o no por el correspondiente Mercado, podrá acordar y habilitar que uno o más de sus clientes realice operaciones tendientes a proveer liquidez a determinadas especies y/o instrumentos. Esta afirmación es:",o:["Verdadera","Verdadera sólo si el cliente es inversor calificado","Verdadera sólo si está habilitado por el Mercado","Falsa"],a:3,e:"Falsa: el hacedor no puede, por su cuenta, habilitar a sus clientes a cumplir la función de proveer liquidez.",r:"M5 · P94"},
{id:"M5-96",m:5,q:"Los informes de calificación, emitidos por los Agentes de Calificación de Riesgos, no deben ser considerados una publicidad, propaganda, difusión o recomendación para adquirir, vender o negociar valores negociables o del instrumento objeto de calificación. Esta afirmación es:",o:["Verdadera","Falsa: equivalen a una recomendación de compra","Falsa","Verdadera sólo para valores con oferta privada"],a:0,e:"Verdadera: la calificación es una opinión sobre el riesgo, no una recomendación de inversión.",r:"M5 · P95"},
{id:"M5-41",m:5,q:"¿Quiénes están legalmente obligados a inscribirse en el Registro de Proveedores de Servicios de Activos Virtuales de la CNV?",o:["Sólo las personas jurídicas constituidas como sociedades anónimas que realicen en el país actividades con activos virtuales","Todas las personas humanas residentes en la República Argentina y personas jurídicas que realicen en el país una o más de las actividades comprendidas en la definición de PSAV del art. 4° bis de la Ley 25.246","Sólo quienes custodien activos virtuales de terceros, sean personas humanas o jurídicas","Sólo los exchanges que operen con más de 1.000 usuarios residentes en el país"],a:1,e:"Alcance amplio: personas humanas residentes y personas jurídicas que hagan en el país alguna de esas actividades.",r:"M5 · P96"},
{id:"M5-97",m:5,q:"¿El tipo societario por sí mismo impide la inscripción como Proveedores de Servicios de Activos Virtuales?",o:["Sí; sólo pueden inscribirse sociedades anónimas","Sí; quedan excluidas las sociedades de responsabilidad limitada","No; lo determinante son los requisitos prudenciales, patrimoniales y de idoneidad que establece la CNV","No, porque la inscripción es voluntaria"],a:2,e:"La CNV no mira la forma societaria sino el cumplimiento de requisitos prudenciales, patrimoniales y de idoneidad.",r:"M5 · P97"},
{id:"M5-98",m:5,q:"¿Cuál es el monto del patrimonio neto mínimo exigido a las personas jurídicas que soliciten inscripción como PSAV?",o:["No se exige patrimonio neto mínimo","Un monto único, igual para todos los PSAV","El mismo que se exige a un ALyC Integral","Depende de la categoría en la que solicite su inscripción"],a:3,e:"No hay un monto único: el patrimonio neto mínimo varía según la categoría de inscripción.",r:"M5 · P98"},
{id:"M5-99",m:5,q:"¿Qué actividad puede realizar una persona humana para inscribirse como PSAV, según las Normas CNV?",o:["Custodia de activos virtuales de terceros","Emisión de activos virtuales con oferta pública","Administración de carteras de activos virtuales de terceros","Actividades de intercambio entre activos virtuales y moneda de curso legal y/o intercambio entre una o más formas de activos virtuales"],a:3,e:"La persona humana sólo puede inscribirse para actividades de intercambio: activos virtuales contra moneda de curso legal o entre activos virtuales.",r:"M5 · P99"},
{id:"M5-100",m:5,q:"De acuerdo con lo establecido por la Ley N° 27.739, la Comisión Nacional de Valores es el organismo encargado de:",o:["Regular todos los activos virtuales, califiquen o no como valores negociables","Emitir activos virtuales oficiales","Registrar a los PSAV sin regular ningún activo virtual","Regular a los PSAV y a los activos virtuales que califiquen como valores negociables, según el art. 2° de la Ley N° 26.831"],a:3,e:"La CNV regula a los PSAV y, en cuanto a los activos, sólo a los que califican como valores negociables.",r:"M5 · P100"},
{id:"M5-101",m:5,q:"¿Cuál de los siguientes requisitos aplica a las sociedades extranjeras para poder inscribirse como PSAV?",o:["Basta con estar registradas en su país de origen y designar un apoderado local","Deben constituir una sociedad anónima local con capital mínimo","Deben estar inscriptas en los términos del art. 118 de la Ley N° 19.550, bajo cualquiera de las formas previstas: sucursal o representación permanente","No pueden inscribirse bajo ninguna forma"],a:2,e:"Se exige la inscripción del art. 118 de la Ley 19.550, como sucursal o representación permanente.",r:"M5 · P101"},
{id:"M5-42",m:5,q:"¿Una persona jurídica que se encuentra inscripta en la CNV y bajo la fiscalización del Organismo conforme al régimen de la Ley N° 26.831 puede solicitar la inscripción en el Registro de PSAV?",o:["Sí, sin restricciones","Sí, si constituye una unidad de negocio separada","No, ya que ello es una causal de exclusión para operar como PSAV","Sí, con autorización previa de la UIF"],a:2,e:"Incompatibilidad expresa: estar ya bajo fiscalización de la CNV por la Ley 26.831 es causal de exclusión.",r:"M5 · P102"},
{id:"M5-43",m:5,q:"¿Qué recomendación le daría Usted a una persona que quiere realizar inversiones en activos virtuales?",o:["Operar únicamente con billeteras del exterior","Invertir sólo en activos con calificación de riesgo","Operar sólo con PSAV registrados en la CNV y conocer los riesgos a los que se está expuesto al realizar operaciones con activos virtuales","Evitar toda operación con activos virtuales"],a:2,e:"Registro + comprensión de los riesgos: operar sólo con PSAV registrados en la CNV sabiendo a qué se expone.",r:"M5 · P103"},
{id:"M5-45",m:5,q:"En un aumento de capital del 100% por suscripción, con una prima de $2,00, si el último precio antes del inicio del período de suscripción es de $4,00, el precio paridad será:",o:["$3,00","$3,50","$2,50","$4,00"],a:1,e:"El precio de emisión es VN + prima = $3. Paridad = (4×1 + 3×1)/2 = $3,50.",r:"M5 · P104"},
{id:"M5-46",m:5,q:"En un aumento de capital del 200% por suscripción de acciones a un precio de emisión de $1,20, si el último precio antes del inicio del período de suscripción es de $1,50, el precio del derecho de suscripción será:",o:["$0,30","$0,10","$0,20","$0,15"],a:2,e:"Paridad = (1×1,50 + 2×1,20)/3 = $1,30. Derecho = precio anterior − paridad = 1,50 − 1,30 = $0,20.",r:"M5 · P105"},
{id:"M5-102",m:5,q:"En un aumento de capital por suscripción a razón de 0,50 acciones nuevas por cada una de tenencia actual, con una prima de $0,45, si el último precio antes del inicio del período de suscripción es de $1,50, el precio del derecho de suscripción será:",o:["$0,0333","$0,0500","$0,0167","$0,3500"],a:2,e:"Emisión = VN + prima = $1,45. Paridad = (1,50×1 + 1,45×0,5)/1,5 = $1,4833. Derecho = 1,50 − 1,4833 = $0,0167.",r:"M5 · P106"},
{id:"M5-103",m:5,q:"En un aumento de capital por suscripción a razón de 1 acción nueva por cada 3 de tenencia actual, con una prima de $2,00, si el último precio antes del inicio del período de suscripción es de $4,00, el precio paridad será:",o:["$3,50","$3,75","$3,00","$3,25"],a:1,e:"Emisión = 1 + 2 = $3. Paridad = (4×3 + 3×1)/4 = $3,75.",r:"M5 · P107"},
{id:"M5-104",m:5,q:"En una suscripción de acciones a razón de 2 acciones nuevas por cada una de tenencia actual, con una prima de emisión de $3, si el último precio antes del inicio del período de suscripción es de $5, el precio del derecho de suscripción será:",o:["$0,667","$1,333","$1,000","$0,333"],a:0,e:"Emisión = 1 + 3 = $4. Paridad = (5×1 + 4×2)/3 = $4,333. Derecho = 5 − 4,333 = $0,667.",r:"M5 · P108"},
{id:"M5-47",m:5,q:"En una suscripción, aplicando el método de la subasta, el precio de corte determinado es $2,10, correspondiendo asignar 300 acciones a ese nivel de precio. Las ofertas recibidas a ese precio cronológicamente fueron 1°: 300 acciones, 2°: 50 acciones, 3°: 250 acciones. La asignación final de las 300 acciones será:",o:["1°: 300 acciones / 2°: 0 / 3°: 0, por orden cronológico","1°: 150 acciones / 2°: 25 acciones / 3°: 125 acciones","1°: 100 acciones / 2°: 100 acciones / 3°: 100 acciones","1°: 250 acciones / 2°: 50 acciones / 3°: 0"],a:1,e:"Al precio de corte se prorratea: hay 600 pedidas para 300, así que cada oferta recibe el 50% de lo que pidió.",r:"M5 · P109"},
{id:"M5-22",m:5,q:"Se efectúa una caución de 1.000 acciones de VN $1 aforadas al 50%. Precios: contado normal al momento de la caución $3,00; contado inmediato al momento de la caución $3,05; último cierre contado normal $3,03. Intereses $20. Gastos $3. El tomador percibe en la apertura:",o:["$1.515","$1.518","$1.495","$1.500"],a:2,e:"Se valoriza al último cierre de contado normal: 1.000 × $3,03 = $3.030 × 50% de aforo = $1.515, menos $20 de intereses = $1.495.",r:"M5 · P110"},
{id:"M5-105",m:5,q:"Se efectúa una caución de 1.000 acciones de VN $1 aforadas al 50%. Precios: contado normal al momento de la caución $3,00; contado inmediato al momento de la caución $3,05; último cierre contado normal $3,03. Intereses $20. Gastos $3. El colocador percibe al vencimiento:",o:["$1.518","$1.495","$1.512","$1.535"],a:2,e:"El colocador entregó 1.515 − 20 = $1.495 y al vencimiento cobra eso más los intereses, neto de gastos: 1.495 + 20 − 3 = $1.512.",r:"M5 · P111"},
{id:"M5-23",m:5,q:"Se efectúa una caución de 1.000 acciones de VN $1 de una especie para la que el aforo es el 50%. Precios: contado normal al momento de la caución $3,00; contado inmediato al momento de la caución $3,05; último cierre contado normal $3,03. Intereses $20. Gastos $3. El tomador abona al vencimiento:",o:["$1.518","$1.535","$1.512","$1.495"],a:0,e:"Devuelve lo recibido más intereses y gastos: 1.495 + 20 + 3 = $1.518.",r:"M5 · P112"},
{id:"M5-106",m:5,q:"Se efectúa una caución de 1.000 acciones de VN $10 de una especie para la que el aforo es el 50%. Precios: contado normal al momento de la caución $10,00; contado inmediato al momento de la caución $10,30; último cierre contado normal $10,20. El tomador percibe en la apertura:",o:["$50.000 menos los intereses","$51.000 menos los intereses","$51.500 menos los intereses","$51.000 más los intereses"],a:1,e:"Se valoriza al último cierre de contado normal: 1.000 × VN $10 × $10,20 = $102.000; con aforo del 50%, $51.000, y el tomador recibe eso menos los intereses.",r:"M5 · P113"},
{id:"M5-107",m:5,q:"Se efectúa una caución de 1.000 acciones de VN $10 de una especie para la que el aforo es el 50%. Precios: contado normal al momento de la caución $10,00; contado inmediato al momento de la caución $10,30; último cierre contado normal $10,20. El colocador percibirá al vencimiento:",o:["$51.000 más los intereses y los gastos","$50.000 menos los gastos","$51.500 menos los gastos","$51.000 menos los gastos"],a:3,e:"Entregó $51.000 menos los intereses; al vencimiento recupera eso más los intereses, neto de gastos: $51.000 menos los gastos.",r:"M5 · P114"},
{id:"M5-108",m:5,q:"Si la tasa efectiva adelantada para 30 días es 3,7%, ¿cuál es la tasa nominal anual vencida para 90 días equivalente a la dada?",o:["48,5653%","47,9001%","46,7463%","45,0167%"],a:0,e:"Vencida a 30 días: 0,037/0,963 = 3,8422%. A 90 días: 1,038422³ − 1 = 11,975%. Nominal anual: 11,975% × 365/90 = 48,5653%.",r:"M5 · P115"},
{id:"M5-109",m:5,q:"Si la tasa nominal anual adelantada para 30 días es 45%, ¿cuál es la tasa nominal anual vencida para 7 días equivalente a la dada?",o:["46,7283%","45,6523%","46,0555%","46,0706%"],a:2,e:"Adelantada a 30 días: 45% × 30/365 = 3,6986%; vencida: 3,6986%/(1 − 3,6986%) = 3,8407%. A 7 días: 1,038407^(7/30) − 1; por 365/7 da 46,0555%.",r:"M5 · P116"},
{id:"M5-110",m:5,q:"Si la tasa nominal anual vencida para 182 días es 48%, ¿cuál es la tasa efectiva anual adelantada equivalente a la dada?",o:["53,7782%","38,7302%","34,9325%","34,9713%"],a:3,e:"Efectiva a 182 días: 48% × 182/365 = 23,934%. TEA vencida: 1,23934^(365/182) − 1 = 53,778%. Adelantada: 0,53778/1,53778 = 34,9713%.",r:"M5 · P117"},
{id:"M5-111",m:5,q:"Cuando un bono cotiza a la par: la TIR, la tasa del cupón y el Current Yield son iguales. Esta afirmación es:",o:["Falsa: la TIR siempre supera al cupón","Verdadera","Falsa","Verdadera sólo en bonos cupón cero"],a:1,e:"Verdadera: a la par el precio es igual al valor nominal, así que cupón sobre precio, cupón sobre VN y TIR coinciden.",r:"M5 · P118"},
{id:"M5-112",m:5,q:"Cuando se espera que baje la tasa de interés de mercado los bonos que más se van a valorizar son los que tienen menor duration modificada. Esta afirmación es:",o:["Falsa","Verdadera","Verdadera sólo para bonos a la par","Verdadera sólo para bonos cupón cero"],a:0,e:"Falsa: la duration modificada mide la sensibilidad del precio a la tasa, así que ante una baja se valorizan más los de mayor duration.",r:"M5 · P119"},
{id:"M5-113",m:5,q:"Si el capital invertido en una caución colocadora de dinero es de $100.000 y la tasa de interés negociada en el mercado es del 30%, considerando que el plazo de la operación es de 30 días, los intereses de la operación ascienden a la suma de:",o:["$2.465,75","$2.500,00","$2.179,84","$30.000,00"],a:0,e:"Tasa nominal anual, base 365: 100.000 × 30% × 30/365 = $2.465,75.",r:"M5 · P120"},
{id:"M5-55",m:5,q:"Un inversor está vendido en el mercado de contado de un cierto activo. Tiene la expectativa de que el precio baje, entonces:",o:["Debe comprar futuros para cubrirse de la baja","Debe vender futuros para cubrir su posición","No necesita cobertura en el mercado de futuros","Debe comprar una put para protegerse"],a:2,e:"Su posición vendida ya se beneficia con la baja que espera: no hay nada que cubrir en futuros.",r:"M5 · P121"},
{id:"M5-53",m:5,q:"Una opción que cotiza en el mercado está out the money, entonces:",o:["No tiene ningún valor y se extingue de inmediato, sin que el comprador pueda venderla","No tiene valor intrínseco, pero sí tiene valor temporal, por lo tanto no será ejercida pero sí puede ser vendida por el comprador","Tiene valor intrínseco pero no valor temporal, por lo tanto conviene ejercerla de inmediato","Debe ejercerse antes del vencimiento para no perder la prima pagada por el comprador"],a:1,e:"Prima = valor intrínseco + valor tiempo. Out the money: intrínseco cero, tiempo positivo; no se ejerce, pero se puede vender.",r:"M5 · P122"},
{id:"M5-52",m:5,q:"Un inversor compró una opción de venta con precio de ejercicio de $500, pagando una prima de $4. En el presente el precio de mercado del activo subyacente es de $600. ¿Qué decisión toma el inversor?",o:["Ejerce la opción y gana $96","Ejerce la opción para limitar la pérdida a $4","No ejerce la opción y pierde la prima pagada de $4","Ejerce la opción y pierde $104"],a:2,e:"Una put sólo conviene si el precio cae por debajo del ejercicio. Con el subyacente en $600 está out the money: no se ejerce y se pierde la prima.",r:"M5 · P123"},
{id:"M5-127",m:5,q:"En segmentos garantizados por CCP, el fondo de garantía cubre incumplimientos:",o:["De los inversores minoristas frente a su ALyC","De los emisores en el pago de los servicios de renta y amortización","Entre Agentes (operaciones garantizadas)","De cualquier operación, garantizada o bilateral"],a:2,e:"El fondo de garantía cubre los incumplimientos entre Agentes en operaciones garantizadas, no los de clientes ni emisores.",r:"M5 · P124"},
{id:"M5-114",m:5,q:"El canal oficial para publicar avisos de emisión y hechos relevantes es:",o:["La Autopista de la Información Financiera","El Boletín Oficial","El sitio web institucional del emisor","El boletín diario del mercado donde lista"],a:0,e:"La AIF de la CNV es el canal oficial para avisos de emisión y hechos relevantes.",r:"M5 · P125"},
{id:"M5-128",m:5,q:"La redistribución de market data en tiempo real a clientes ADM:",o:["Prohibida para los Agentes","Sujeta a arancel del Mercado","Sin costo, a cargo exclusivo del Agente","Sujeta a autorización previa de la CNV"],a:1,e:"La market data en tiempo real que el agente redistribuye a sus clientes ADM está sujeta al arancel que fije el Mercado.",r:"M5 · P126"},
{id:"M5-129",m:5,q:"La Comisión Nacional de Valores regula:",o:["A los PSAV, mientras que los activos virtuales los regula el BCRA","Únicamente a las criptomonedas negociadas en mercados autorizados","A los activos virtuales, mientras que a los PSAV sólo los registra la UIF","A los Proveedores de Servicios de Activos Virtuales y a los activos virtuales que califiquen como valores negociables"],a:3,e:"La CNV regula a los PSAV y, entre los activos virtuales, a los que califican como valores negociables.",r:"M5 · P127"},
{id:"M5-130",m:5,q:"Durante su período de presencia, el Hacedor debe mantener ofertas simultáneas de compra/venta respetando spread mínimo. Esta afirmación es:",o:["Verdadera","Verdadera sólo fuera del período de presencia","Falsa: sólo debe mantener ofertas de venta","Falsa"],a:0,e:"Verdadera: durante su período de presencia el hacedor tiene que estar de los dos lados a la vez, respetando el spread mínimo.",r:"M5 · P128"}
);
